#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}
int main(void) {
    const char *g[] = {" _ ", "| |", "|_|", "   "};
    char o[100];
    assert(convert(g, 4, o) && !strcmp(o, "0"));
    const char *b[] = {"   ", "  |", "  |", "   ", "???", "???", "???", "   "};
    assert(convert(b, 8, o) && !strcmp(o, "1,?"));
    assert(!convert(g, 3, o));
    const char *c[] = {"  ", "  ", "  ", "  "};
    assert(!convert(c, 4, o));
    {
        const char *values[] = {" _ ", "| |", "|_|", "   "};
        char actual[1000];
        assert(convert(values, 4, actual));
        assert(!strcmp(actual, "0"));
    }
    {
        const char *values[] = {"   ", "  |", "  |", "   "};
        char actual[1000];
        assert(convert(values, 4, actual));
        assert(!strcmp(actual, "1"));
    }
    {
        const char *values[] = {"   ", "  _", "  |", "   "};
        char actual[1000];
        assert(convert(values, 4, actual));
        assert(!strcmp(actual, "?"));
    }
    {
        const char *values[] = {
            "       _     _        _  _ ", "  |  || |  || |  |  || || |",
            "  |  ||_|  ||_|  |  ||_||_|", "                           "};
        char actual[1000];
        assert(convert(values, 4, actual));
        assert(!strcmp(actual, "110101100"));
    }
    {
        const char *values[] = {
            "       _     _           _ ", "  |  || |  || |     || || |",
            "  |  | _|  ||_|  |  ||_||_|", "                           "};
        char actual[1000];
        assert(convert(values, 4, actual));
        assert(!strcmp(actual, "11?10?1?0"));
    }
    {
        const char *values[] = {" _ ", " _|", "|_ ", "   "};
        char actual[1000];
        assert(convert(values, 4, actual));
        assert(!strcmp(actual, "2"));
    }
    {
